// ---------------------------------------------------------------------------
// DeliveryStatus validate_status — structured error for cross-repo comparison
// ---------------------------------------------------------------------------

#[test]
fn test_validate_status_all_5_python_variants() {
    for status_str in &["proposed", "accepted", "needs_revision", "rejected", "superseded"] {
        let result = DeliveryStatus::validate_status(status_str);
        assert!(
            result.is_ok(),
            "validate_status({status_str}) must succeed for Python-emitted status"
        );
    }
}

#[test]
fn test_validate_status_rejects_unknown() {
    for bogus in &["pending", "cancelled", "in_review", "completed", ""] {
        let err = DeliveryStatus::validate_status(bogus).unwrap_err();
        assert_eq!(err.error, "validation_failed");
        assert_eq!(err.reason, "unsupported_status");
        assert_eq!(err.value.as_deref(), Some(*bogus));
    }
}

